using System.Collections.Generic;
using UnityEngine;
namespace OceanariumFishing.Editor
{
    // All geometry is generated by Unity; no external models or textures.
    public static class CozyGeometry
    {
        public static Mesh RoundedBox()
        {
            var v=new List<Vector3>();var n=new List<Vector3>();var t=new List<int>();var uv=new List<Vector2>();
            float[] grid={-.5f,-.43f,.43f,.5f};
            for(int face=0;face<6;face++)
            {
                Vector3 normal=face==0?Vector3.right:face==1?Vector3.left:face==2?Vector3.up:face==3?Vector3.down:face==4?Vector3.forward:Vector3.back;
                Vector3 u=Vector3.Cross(normal,Mathf.Abs(normal.y)>.5f?Vector3.forward:Vector3.up),w=Vector3.Cross(normal,u);
                int start=v.Count;
                for(int y=0;y<4;y++)for(int x=0;x<4;x++)
                {
                    Vector3 p=normal*.5f+u*grid[x]+w*grid[y];
                    Vector3 inner=new Vector3(Mathf.Clamp(p.x,-.43f,.43f),Mathf.Clamp(p.y,-.43f,.43f),Mathf.Clamp(p.z,-.43f,.43f));
                    Vector3 dir=(p-inner).normalized;v.Add(inner+dir*.07f);n.Add(dir);uv.Add(new Vector2(grid[x]+.5f,grid[y]+.5f));
                }
                for(int y=0;y<3;y++)for(int x=0;x<3;x++){int a=start+y*4+x;t.AddRange(new[]{a,a+1,a+4,a+1,a+5,a+4});}
            }
            var m=new Mesh();m.SetVertices(v);m.SetUVs(0,uv);m.SetNormals(n);m.SetTriangles(t,0);m.RecalculateBounds();return m;
        }
        public static Mesh Orb(int seed=0,int sides=16,int rings=10,float irregular=.08f)
        {
            var v=new List<Vector3>();var t=new List<int>();var uv=new List<Vector2>();
            for(int y=0;y<=rings;y++)for(int x=0;x<=sides;x++)
            {
                float a=x*Mathf.PI*2/sides,b=y*Mathf.PI/rings;
                Vector3 p=new Vector3(Mathf.Sin(b)*Mathf.Cos(a),Mathf.Cos(b),Mathf.Sin(b)*Mathf.Sin(a));
                float r=.5f*(1+irregular*(Mathf.Sin(p.x*8+seed)*Mathf.Sin(p.z*6+seed*.7f)+.5f*Mathf.Cos(p.y*11+seed)));
                v.Add(p*r);uv.Add(new Vector2(x/(float)sides,y/(float)rings));
                if(y<rings && x<sides){int k=y*(sides+1)+x;t.AddRange(new[]{k,k+1,k+sides+1,k+1,k+sides+2,k+sides+1});}
            }
            var m=new Mesh();m.SetVertices(v);m.SetUVs(0,uv);m.SetTriangles(t,0);m.RecalculateNormals();m.RecalculateBounds();return m;
        }
        public static Mesh Tube(Vector3[] points,float[] radii,int sides=8)
        {
            var v=new List<Vector3>();var t=new List<int>();var uv=new List<Vector2>();
            for(int j=0;j<points.Length;j++)
            {
                Vector3 dir=(points[Mathf.Min(j+1,points.Length-1)]-points[Mathf.Max(j-1,0)]).normalized;
                Vector3 side=Vector3.Cross(dir,Mathf.Abs(dir.y)>.95f?Vector3.forward:Vector3.up).normalized,up=Vector3.Cross(dir,side);
                for(int i=0;i<=sides;i++){float a=i*Mathf.PI*2/sides;v.Add(points[j]+(side*Mathf.Cos(a)+up*Mathf.Sin(a))*radii[j]);uv.Add(new Vector2(i/(float)sides,j/(float)(points.Length-1)));}
                if(j>0)for(int i=0;i<sides;i++){int a=(j-1)*(sides+1)+i;t.AddRange(new[]{a,a+1,a+sides+1,a+1,a+sides+2,a+sides+1});}
            }
            int startCap=v.Count;v.Add(points[0]);uv.Add(new Vector2(.5f,.5f));int endCap=v.Count;v.Add(points[points.Length-1]);uv.Add(new Vector2(.5f,.5f));int last=(points.Length-1)*(sides+1);
            for(int j=0;j<sides;j++){t.AddRange(new[]{startCap,j+1,j,endCap,last+j,last+j+1});}
            var m=new Mesh();m.SetVertices(v);m.SetUVs(0,uv);m.SetTriangles(t,0);m.RecalculateNormals();m.RecalculateBounds();return m;
        }
        public static Mesh Frond(float length,float width,float droop)
        {
            var v=new List<Vector3>();var uv=new List<Vector2>();var t=new List<int>();
            // A continuous folded blade with small edge notches, like the supplied broad tropical leaves.
            const int steps=28;
            for(int j=0;j<=steps;j++)
            {
                float f=j/(float)steps,w=Mathf.Pow(Mathf.Max(0,Mathf.Sin(f*Mathf.PI)),.72f)*width;
                if(j%3==2 && j>3 && j<25)w*=.79f;
                float y=.38f*Mathf.Sin(f*Mathf.PI)-droop*f*f,z=f*length;
                v.Add(new Vector3(-w,y-.095f*Mathf.Sin(f*Mathf.PI),z));v.Add(new Vector3(0,y+.06f*Mathf.Sin(f*Mathf.PI),z));v.Add(new Vector3(w,y-.095f*Mathf.Sin(f*Mathf.PI),z));
                uv.Add(new Vector2(0,f));uv.Add(new Vector2(.5f,f));uv.Add(new Vector2(1,f));
                if(j<steps)for(int k=0;k<2;k++){int a=j*3+k;t.AddRange(new[]{a,a+3,a+1,a+1,a+3,a+4});}
            }
            var m=new Mesh();m.SetVertices(v);m.SetUVs(0,uv);m.SetTriangles(t,0);m.RecalculateNormals();m.RecalculateBounds();return m;
        }
    }
}


